function toLines(orderId, items) {
  return items
    .split(",")
    .map((item) => item.trim())
    .filter((item) => item !== "")
    .map((item) => {
      const [sku, quantity] = item.split(" x");
      return { orderId, sku, quantity: Number(quantity) };
    });
}

console.log(toLines(1, "RICE-5KG x2, OIL-1L x1"));
console.log(toLines(2, "CHG-20W x1 ,CABLE-C x3"));

