const categories = [
  { id: 1, parentId: null, name: "Groceries" },
  { id: 2, parentId: null, name: "Electronics" },
  { id: 5, parentId: 2, name: "Accessories" },
  { id: 7, parentId: 5, name: "Chargers" },
];

function breadcrumb(categories, id) {
  const byId = new Map(categories.map((c) => [c.id, c]));
  const names = [];
  let current = byId.get(id);
  while (current) {
    names.unshift(current.name);
    current = current.parentId === null ? undefined : byId.get(current.parentId);
  }
  return names.join(" / ");
}

console.log(breadcrumb(categories, 7));
console.log(breadcrumb(categories, 1));

