const lines = [
  { orderId: 1, quantity: 2, unitPriceKobo: 950000 },
  { orderId: 1, quantity: 1, unitPriceKobo: 280000 },
  { orderId: 2, quantity: 1, unitPriceKobo: 450000 },
];
const payments = [
  { orderId: 1, amountKobo: 2180000, status: "failed" },
  { orderId: 1, amountKobo: 2180000, status: "succeeded" },
];

function summary(lines, payments) {
  const totals = new Map();
  for (const l of lines) totals.set(l.orderId, (totals.get(l.orderId) ?? 0) + l.quantity * l.unitPriceKobo);
  const paid = new Map();
  for (const p of payments) {
    if (p.status === "succeeded") paid.set(p.orderId, (paid.get(p.orderId) ?? 0) + p.amountKobo);
  }
  return [...totals.keys()].sort((a, b) => a - b).map((orderId) => ({
    orderId,
    totalKobo: totals.get(orderId),
    paidKobo: paid.get(orderId) ?? 0,
  }));
}

console.log(summary(lines, payments));

