const emails = ["ada@example.com", "tunde@example.com", "Ada@Example.com", "chioma@example.com", "TUNDE@example.com", "ADA@EXAMPLE.COM"];

function caseDuplicates(emails) {
  const groups = new Map();
  for (const email of emails) {
    const key = email.toLowerCase();
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(email);
  }
  return [...groups.values()].filter((group) => group.length > 1);
}

console.log(caseDuplicates(emails));

