const categories = [
  { id: 1, parentId: null, name: "Groceries" },
  { id: 2, parentId: null, name: "Electronics" },
  { id: 3, parentId: 1, name: "Oils" },
  { id: 4, parentId: 1, name: "Grains" },
  { id: 5, parentId: 2, name: "Audio" },
  { id: 6, parentId: 2, name: "Accessories" },
  { id: 7, parentId: 6, name: "Chargers" },
];

function printTree(categories, parentId = null, depth = 0) {
  const children = categories
    .filter((c) => c.parentId === parentId)
    .sort((a, b) => a.name.localeCompare(b.name));
  for (const child of children) {
    console.log("  ".repeat(depth) + child.name);
    printTree(categories, child.id, depth + 1);
  }
}

printTree(categories);
